'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var Float64Array = require( '@stdlib/array/float64' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var resolveEnum = require( '@stdlib/blas/base/matrix-triangle-resolve-enum' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var dspmv = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float64', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dspmv, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( dspmv.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function performs the matrix-vector operation `y = alpha*A*x + beta*y` (upper)', function test( t ) {
	var expected;
	var alpha;
	var uplo;
	var beta;
	var xbuf;
	var ybuf;
	var Abuf;
	var A;
	var x;
	var y;
	var v;

	xbuf = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	ybuf = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	Abuf = new Float64Array( [ 1.0, 2.0, 3.0, 1.0, 2.0, 1.0 ] );
	A = vector( Abuf, 6, 1, 0 );
	x = vector( xbuf, 3, 1, 0 );
	y = vector( ybuf, 3, 1, 0 );
	uplo = scalar2ndarray( resolveEnum( 'upper' ), {
		'dtype': 'int8'
	});
	alpha = scalar2ndarray( 1.0, {
		'dtype': 'float64'
	});
	beta = scalar2ndarray( 1.0, {
		'dtype': 'float64'
	});

	v = dspmv( [ A, x, y, uplo, alpha, beta ] );

	expected = new Float64Array( [ 15.0, 12.0, 13.0 ] );
	t.strictEqual( v, y, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( getData( v ), expected ), true, 'returns expected value' );

	xbuf = new Float64Array( [ 1.0, 1.0, 1.0 ] );
	ybuf = new Float64Array( [ 1.0, 1.0, 1.0 ] );
	Abuf = new Float64Array( [ 1.0, 4.0, 2.0, 5.0, 3.0, 6.0 ] );
	A = vector( Abuf, 6, 1, 0 );
	x = vector( xbuf, 3, 1, 0 );
	y = vector( ybuf, 3, 1, 0 );
	uplo = scalar2ndarray( resolveEnum( 'upper' ), {
		'dtype': 'int8'
	});
	alpha = scalar2ndarray( 2.0, {
		'dtype': 'float64'
	});
	beta = scalar2ndarray( 2.0, {
		'dtype': 'float64'
	});

	v = dspmv( [ A, x, y, uplo, alpha, beta ] );

	expected = new Float64Array( [ 16.0, 26.0, 24.0 ] );
	t.strictEqual( v, y, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( getData( v ), expected ), true, 'returns expected value' );

	t.end();
});

